('legal_disclaimer','Yojo Solutions provides consulting, readiness and assessment services. Certifications and attestation reports are issued only by independent accredited bodies or licensed firms.','company','Footer disclaimer','textarea',28);
INSERT INTO `pages` (`slug`,`title`,`content`) VALUES
('privacy-policy','Privacy Policy','<p><strong>Placeholder — please have this policy reviewed by qualified counsel before publication.</strong></p><p>This Privacy Policy explains how Yojo Solutions ("we", "us") collects and uses personal data when you visit this website or contact us.</p><h2>Information we collect</h2><ul><li>Details you submit through enquiry, consultation and assessment forms: name, company, business email, phone, industry, company size, and your message.</li><li>Technical data such as IP address and browser type, used for security and spam prevention.</li></ul><h2>How we use information</h2><p>We use your information to respond to enquiries, schedule consultations, prepare proposals and improve our services. We do not sell personal data.</p><h2>Retention</h2><p>Enquiry data is retained only as long as necessary for the purposes above or as required by law.</p><h2>Your rights</h2><p>You may request access, correction or erasure of your personal data, or withdraw consent, by emailing us at the address on our Contact page.</p><h2>Contact</h2><p>For privacy questions, contact us using the details on the Contact page.</p>'),
('cookie-policy','Cookie Policy','<p><strong>Placeholder — review before publication.</strong></p><p>This website uses a minimal number of cookies.</p><h2>Strictly necessary cookies</h2><p>A session cookie keeps forms secure (CSRF protection) and keeps administrators signed in. These cookies are essential and do not track you across sites.</p><h2>Preferences</h2><p>We store your cookie-banner choice in your browser\'s local storage.</p><h2>Analytics</h2><p>No third-party analytics or advertising cookies are set by default. If analytics are added in future, this policy will be updated and consent requested where required.</p>'),
('terms-and-conditions','Terms and Conditions','<p><strong>Placeholder — review before publication.</strong></p><p>By using this website you agree to these terms.</p><h2>Information only</h2><p>Content on this website is general information and does not constitute legal, audit or professional advice for your specific circumstances. Engagements are governed by a separate signed agreement.</p><h2>Self-assessment tool</h2><p>The Audit Readiness Assessment produces an indicative, preliminary result based solely on your answers. It is not an audit, certification or assurance opinion.</p><h2>Certifications</h2><p>Yojo Solutions does not issue certifications or attestation reports. These are issued by independent accredited bodies or licensed firms.</p><h2>Intellectual property</h2><p>All content on this website is owned by Yojo Solutions unless otherwise stated.</p><h2>Limitation of liability</h2><p>To the extent permitted by law, we are not liable for losses arising from reliance on website content.</p>');
INSERT INTO `service_categories` (`id`,`slug`,`name`,`tagline`,`summary`,`description`,`engagement_note`,`page_type`,`icon`,`sort_order`) VALUES
(1,'governance-risk-compliance','Governance, Risk & Compliance','Framework-aligned programmes that hold up under audit.','Readiness assessments, implementation support and internal audits for ISO, SOC 2, PCI DSS, privacy laws and control frameworks.','We help organisations translate demanding standards into practical controls, evidence and governance routines — so that external audits become a confirmation of work already done rather than a scramble.','Our role is consulting, implementation support, readiness assessment and internal audit. Formal certification is issued only by accredited certification bodies, SOC 2 reports only by licensed CPA firms, and PCI DSS Reports on Compliance only by Qualified Security Assessors (QSAs). We prepare you for those engagements and can coordinate with your chosen assessor — we do not issue certificates ourselves.','compliance','scale',1),
(2,'cybersecurity-audit-vapt','Cybersecurity Audit & VAPT','Find exploitable weaknesses before someone else does.','Authorised vulnerability assessment and penetration testing across web, mobile, API, network, cloud and source code.','Manual-led, standards-aligned security testing performed only against assets you own or are authorised to test, under a signed scope and rules of engagement.','All testing is performed only after written authorisation from the asset owner, within an agreed scope, testing window and rules of engagement. We never test third-party systems without their owner\'s permission.','security','radar',2),
(3,'it-audit-assurance','IT Audit & Technology Assurance','Independent evidence that your technology controls work.','ITGC, application controls, access, change, operations, cloud, third-party and continuity audits.','Risk-based technology audits that test both design and operating effectiveness of controls — giving boards, regulators and statutory auditors confidence in your IT environment.','Our IT audits are internal or advisory audits that support management, audit committees and external auditors. They do not replace a statutory financial audit or a regulator-mandated audit performed by an empanelled firm unless we are specifically empanelled for it.','assurance','clipboard',3),
(4,'data-privacy-risk-advisory','Data Privacy & Regulatory Compliance','Privacy and risk programmes built for real regulators.','Enterprise and cyber risk, privacy impact assessments, data protection governance, policies, vendor risk and gap assessments.','Pragmatic advisory that connects regulatory obligations to day-to-day processes, data flows and decision-making — with clear ownership and measurable risk reduction.','Our advisory services provide professional guidance on risk and data protection practices. They are not legal advice; where a legal opinion is required we recommend engaging qualified legal counsel, and we are happy to work alongside them.','advisory','lock',4);
INSERT INTO `services` (`id`,`category_id`,`slug`,`title`,`menu_group`,`engagement_type`,`icon`,`summary`,`intro`,`meaning`,`why_needed`,`requirements`,`methodology`,`scope`,`security_areas`,`deliverables`,`reporting`,`remediation`,`benefits`,`meta_title`,`meta_description`,`is_featured`,`sort_order`) VALUES
(1,1,'iso-27001-consulting','ISO/IEC 27001 Consulting & Audit Readiness','governance','Consulting · Implementation · Internal audit','shield-check','Design, implement and internally audit an Information Security Management System ready for accredited certification.','ISO/IEC 27001 is the internationally recognised standard for information security management. We help you build an ISMS that is proportionate to your risks, embedded in operations and ready for a certification body.','ISO/IEC 27001:2022 defines requirements for establishing, implementing, maintaining and continually improving an ISMS. Annex A provides 93 reference controls grouped into organisational, people, physical and technological themes, selected through risk assessment and documented in a Statement of Applicability.','Enterprise customers, regulators and investors increasingly expect independent assurance over how information is protected. A well-run ISMS reduces incidents, shortens security questionnaires and creates a repeatable way to manage change.','ISMS scope & context :: Clauses 4–5 — boundaries, interested parties and leadership commitment.\nRisk assessment & treatment :: Clause 6 — documented methodology and treatment plan.\nStatement of Applicability :: Justified inclusion or exclusion of Annex A controls.\nSupport & operation :: Competence, awareness, documented information and operational planning.\nPerformance evaluation :: Monitoring, internal audit and management review.\nImprovement :: Nonconformity handling and corrective action.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','ISO/IEC 27001 Consulting & Audit Readiness | Yojo Solutions','Design, implement and internally audit an Information Security Management System ready for accredited certification.',1,1),
(2,1,'soc-2-readiness','SOC 2 Type I & Type II Readiness','governance','Readiness assessment · Control design · Audit coordination','badge','Prepare your controls and evidence for a SOC 2 examination against the AICPA Trust Services Criteria.','SOC 2 is the assurance report most often requested by North American customers of SaaS and service providers. We help you select criteria, design controls and run a readiness assessment before your CPA firm begins.','A SOC 2 report is an attestation issued by a licensed CPA firm. Type I evaluates the design of controls at a point in time; Type II evaluates design and operating effectiveness over a period, typically three to twelve months. Reports cover Security and optionally Availability, Processing Integrity, Confidentiality and Privacy.','Prospects frequently make a SOC 2 report a condition of contract. Readiness work avoids qualified opinions, reduces auditor hours and builds evidence habits that survive the observation period.','Trust Services Criteria selection :: Security (Common Criteria) plus relevant optional categories.\nSystem description :: Boundaries, infrastructure, software, people, data and procedures.\nControl environment :: Governance, risk assessment and monitoring controls (CC1–CC5).\nLogical & physical access :: Provisioning, reviews, MFA and termination (CC6).\nSystem operations & change :: Monitoring, incident response and change management (CC7–CC8).\nVendor & risk mitigation :: Third-party oversight and business continuity (CC9).','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','SOC 2 Type I & Type II Readiness | Yojo Solutions','Prepare your controls and evidence for a SOC 2 examination against the AICPA Trust Services Criteria.',1,2),
(3,1,'pci-dss-compliance','PCI DSS Compliance','governance','Gap assessment · Scope reduction · QSA preparation','card','Reduce cardholder-data scope and prepare for PCI DSS v4.0 assessment by a Qualified Security Assessor or via SAQ.','Any organisation that stores, processes or transmits payment card data must protect it under PCI DSS. We help you understand your validation route, shrink scope and close gaps before formal assessment.','The Payment Card Industry Data Security Standard v4.0.x contains 12 principal requirements spanning network security, data protection, vulnerability management, access control, monitoring and policy. Validation is either a Self-Assessment Questionnaire or a Report on Compliance by a QSA, depending on merchant or service-provider level.','Non-compliance can lead to fines from acquiring banks, higher transaction fees and, after a breach, loss of the ability to accept cards. A smaller cardholder-data environment means lower cost and risk.','Network security controls :: Requirements 1–2.\nProtect account data :: Requirements 3–4 — storage and transmission.\nVulnerability management :: Requirements 5–6 — malware protection and secure systems.\nAccess control :: Requirements 7–9.\nMonitoring & testing :: Requirements 10–11 including quarterly scans and penetration tests.\nInformation security policy :: Requirement 12 and targeted risk analyses.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','PCI DSS Compliance | Yojo Solutions','Reduce cardholder-data scope and prepare for PCI DSS v4.0 assessment by a Qualified Security Assessor or via SAQ.',0,3),
(4,1,'iso-22301-business-continuity','ISO 22301 Business Continuity','governance','Consulting · BIA · Exercise facilitation','refresh','Build a Business Continuity Management System that keeps critical services running through disruption.','Disruption is inevitable — outages, cyber incidents, supplier failure or natural events. ISO 22301 provides a structured way to anticipate impact and recover within tolerances your customers can accept.','ISO 22301:2019 specifies requirements for a Business Continuity Management System (BCMS), including business impact analysis, risk assessment, continuity strategies, documented plans and regular exercising.','Regulators, especially in financial services and healthcare, expect demonstrable resilience. Customers increasingly ask for recovery commitments backed by tested plans rather than documents on a shelf.','Business impact analysis :: Prioritised activities, RTOs and RPOs.\nRisk assessment :: Threats to prioritised activities and resources.\nContinuity strategies :: People, premises, technology, information and suppliers.\nPlans & procedures :: Incident response and recovery plans.\nExercising & testing :: Scheduled exercises with lessons learned.\nEvaluation & improvement :: Internal audit and management review.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','ISO 22301 Business Continuity | Yojo Solutions','Build a Business Continuity Management System that keeps critical services running through disruption.',0,4),
(5,1,'iso-42001-ai-management','ISO/IEC 42001 AI Management Systems','advisory','Consulting · Gap assessment · Governance design','cpu','Govern the responsible development and use of AI with an AI Management System aligned to ISO/IEC 42001.','As AI moves into products and decision-making, organisations need governance that addresses bias, transparency, accountability and security. ISO/IEC 42001 is the first management-system standard dedicated to AI.','ISO/IEC 42001:2023 sets requirements for an Artificial Intelligence Management System (AIMS), including AI policy, AI risk and impact assessment, lifecycle controls, data quality, third-party considerations and continual improvement. It follows the same harmonised structure as ISO 27001.','Customers, regulators and emerging laws such as the EU AI Act expect evidence of responsible AI practices. An AIMS creates a defensible, auditable approach before scrutiny arrives.','AI policy & objectives :: Leadership-approved principles and measurable objectives.\nAI risk assessment :: Risks to individuals, groups and society.\nAI system impact assessment :: Documented impacts across the lifecycle.\nData for AI systems :: Quality, provenance and preparation controls.\nLifecycle controls :: Design, verification, deployment, monitoring.\nThird-party & customer relationships :: Responsibilities across the AI supply chain.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','ISO/IEC 42001 AI Management Systems | Yojo Solutions','Govern the responsible development and use of AI with an AI Management System aligned to ISO/IEC 42001.',0,5),
(6,1,'hipaa-compliance','HIPAA Compliance Advisory','privacy','Risk analysis · Safeguard implementation · Advisory','heart','Protect electronic protected health information (ePHI) with HIPAA Security Rule risk analysis and safeguard implementation.','Covered entities and business associates handling US health data must meet the HIPAA Privacy, Security and Breach Notification Rules. We help healthcare and health-tech organisations implement proportionate, documented safeguards.','HIPAA\'s Security Rule requires administrative, physical and technical safeguards for ePHI, underpinned by a documented risk analysis. Business associates must sign Business Associate Agreements and meet many of the same obligations as covered entities.','HIPAA violations carry significant civil penalties and reputational damage. US healthcare customers routinely require evidence of HIPAA safeguards before sharing data with vendors.','Security risk analysis :: Enterprise-wide assessment of risks to ePHI.\nAdministrative safeguards :: Security management, workforce training and contingency planning.\nPhysical safeguards :: Facility access, workstation and device controls.\nTechnical safeguards :: Access control, audit controls, integrity and transmission security.\nBusiness associate agreements :: Contractual obligations with vendors.\nBreach notification :: Procedures for assessment and notification.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','HIPAA Compliance Advisory | Yojo Solutions','Protect electronic protected health information (ePHI) with HIPAA Security Rule risk analysis and safeguard implementation.',0,6),
(7,1,'gdpr-compliance','GDPR Compliance','privacy','Gap assessment · Programme design · DPIA support','globe','Build a defensible data protection programme for processing personal data of individuals in the EU/EEA.','The General Data Protection Regulation applies to organisations worldwide that offer goods or services to, or monitor, people in the EU. We help you understand your obligations and put the right governance in place.','GDPR establishes principles for lawful processing, rights for individuals, accountability obligations such as records of processing and DPIAs, security requirements, breach notification within 72 hours and rules for international transfers.','Supervisory authorities can impose fines of up to 4% of global annual turnover. Beyond penalties, EU customers and partners expect GDPR-aligned contracts and practices.','Lawful basis & transparency :: Articles 6, 12–14.\nData subject rights :: Access, rectification, erasure, portability and objection.\nRecords of processing :: Article 30 register.\nDPIA :: Article 35 for high-risk processing.\nSecurity & breach notification :: Articles 32–34.\nInternational transfers :: SCCs, adequacy and transfer impact assessments.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','GDPR Compliance | Yojo Solutions','Build a defensible data protection programme for processing personal data of individuals in the EU/EEA.',0,7),
(8,1,'dpdpa-compliance','India\'s DPDPA Compliance','privacy','Readiness assessment · Programme design','flag','Prepare for India\'s Digital Personal Data Protection Act, 2023 and its Rules with a practical compliance roadmap.','The DPDP Act establishes India\'s comprehensive framework for digital personal data. Data Fiduciaries need to rethink notices, consent, security safeguards and grievance handling.','The Act sets obligations for Data Fiduciaries — including notice and consent, purpose limitation, reasonable security safeguards, breach intimation to the Data Protection Board and affected individuals, data retention limits and rights for Data Principals. Significant Data Fiduciaries face additional duties such as a DPO, independent data audits and DPIAs.','Penalties under the Act can reach up to ₹250 crore per instance for failure to take reasonable security safeguards. Early preparation avoids rushed changes to products and customer journeys.','Notice & consent :: Clear, itemised notices and verifiable consent.\nConsent managers :: Interfaces with registered consent managers where applicable.\nSecurity safeguards :: Reasonable measures to prevent personal data breaches.\nBreach intimation :: Notification to the Board and affected Data Principals.\nData Principal rights :: Access, correction, erasure, grievance redressal and nomination.\nSignificant Data Fiduciary duties :: DPO, independent data audit and periodic DPIA.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','India\'s DPDPA Compliance | Yojo Solutions','Prepare for India\'s Digital Personal Data Protection Act, 2023 and its Rules with a practical compliance roadmap.',0,8),
(9,1,'nist-cybersecurity-framework','NIST Cybersecurity Framework','governance','Maturity assessment · Target profile · Roadmap','layers','Assess and improve cybersecurity maturity using NIST CSF 2.0 profiles and tiers.','NIST CSF is a flexible, outcome-based framework widely used to communicate cybersecurity posture to boards and to prioritise investment. Version 2.0 adds a dedicated Govern function.','NIST CSF 2.0 organises outcomes into six functions — Govern, Identify, Protect, Detect, Respond and Recover — with categories and subcategories. Organisations create Current and Target Profiles and use implementation Tiers to describe rigour.','Boards want a clear, comparable view of cyber maturity. CSF provides a common language for that conversation and maps neatly to ISO 27001, SOC 2 and sector regulations.','Govern :: Strategy, roles, policy and supply-chain risk management.\nIdentify :: Asset management, risk assessment and improvement.\nProtect :: Identity, awareness, data security and platform security.\nDetect :: Continuous monitoring and adverse event analysis.\nRespond :: Incident management, analysis and communication.\nRecover :: Recovery planning and execution.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','NIST Cybersecurity Framework | Yojo Solutions','Assess and improve cybersecurity maturity using NIST CSF 2.0 profiles and tiers.',0,9),
(10,1,'hitrust-readiness','HITRUST Readiness','governance','Readiness assessment · Control remediation','stack','Prepare for HITRUST e1, i1 or r2 validated assessments with scoping, readiness testing and remediation.','HITRUST is a certifiable framework popular with US healthcare organisations because it harmonises HIPAA, NIST, ISO and other sources into one control set. We help you choose the right assessment and get ready.','The HITRUST CSF offers three validated assessment types — e1 (essentials), i1 (implemented, leading practices) and r2 (risk-based, comprehensive). Validated assessments are performed by an authorised External Assessor and quality-reviewed by HITRUST, which issues the certification.','Large healthcare payers and providers frequently require HITRUST certification from vendors, making it a commercial necessity for health-tech companies.','Assessment selection :: e1, i1 or r2 based on risk and customer demand.\nScoping :: Systems, facilities and organisational boundaries.\nControl maturity :: Policy, procedure and implementation evidence.\nReadiness testing :: Pre-assessment of requirement statements.\nCorrective action plans :: Gaps tracked to closure.\nExternal assessor coordination :: Hand-off to an authorised assessor.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','HITRUST Readiness | Yojo Solutions','Prepare for HITRUST e1, i1 or r2 validated assessments with scoping, readiness testing and remediation.',0,10),
(11,1,'itgc','IT General Controls (ITGC)','it_audit','Control design · Readiness · Internal testing','settings','Design and test IT general controls that support reliable financial reporting and SOX/IFC requirements.','ITGCs are the foundation that allows auditors to trust automated controls and system-generated reports. We help you design pragmatic controls and test them before your statutory auditor does.','IT General Controls are pervasive controls over the IT environment — access to programs and data, program changes, program development and computer operations — that support the integrity of applications relevant to financial reporting.','Weak ITGCs force auditors to expand substantive testing, increasing audit fees and the risk of reported deficiencies under Internal Financial Controls (Companies Act 2013) or SOX.','Access to programs & data :: Provisioning, privileged access and periodic reviews.\nProgram change management :: Authorisation, testing and segregation of duties.\nProgram development :: SDLC controls for new systems.\nComputer operations :: Job scheduling, backups and incident management.\nIPE reliability :: Completeness and accuracy of system reports.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','IT General Controls (ITGC) | Yojo Solutions','Design and test IT general controls that support reliable financial reporting and SOX/IFC requirements.',0,11),
(12,1,'itac','IT Application Controls (ITAC)','it_audit','Control identification · Testing','grid','Identify, design and test automated application controls embedded in your business systems.','Automated controls in ERP and business applications can be more reliable and efficient than manual controls — but only when properly configured and supported by strong ITGCs.','IT Application Controls are automated controls within specific applications, such as input validation, three-way matching, automated calculations, interface controls and system-enforced segregation of duties.','Relying on well-tested automated controls reduces manual effort, error rates and audit sample sizes, and supports scalable growth.','Input controls :: Validation, edit checks and mandatory fields.\nProcessing controls :: Automated calculations and matching.\nOutput controls :: Report completeness and accuracy.\nInterface controls :: Data transfer between systems.\nConfigurable SoD :: System-enforced role conflicts.','Discovery & context :: Understand business objectives, systems in scope, existing certifications and stakeholder expectations.\nGap assessment :: Compare current controls, policies and evidence against each requirement of the framework.\nRisk assessment & treatment :: Identify and rate risks, then agree treatment decisions with accountable owners.\nImplementation support :: Co-develop policies, procedures, control designs and evidence routines with your teams.\nInternal audit :: Independently test controls and the management system before the external assessor arrives.\nExternal audit support :: Help you prepare, respond to auditor queries and close any findings promptly.','Scoping workshop and boundary definition\nPolicy, procedure and control documentation review\nInterviews with process and control owners\nSample-based evidence review\nRisk register and treatment plan development\nAwareness session for leadership and staff',NULL,'Gap Assessment Report :: Requirement-by-requirement status with prioritised actions.\nRisk Register & Treatment Plan :: Rated risks mapped to owners, controls and timelines.\nPolicy & Procedure Set :: Tailored documentation ready for approval.\nImplementation Roadmap :: Phased plan with effort and dependency estimates.\nInternal Audit Report :: Independent findings, observations and corrective actions.\nAudit Readiness Pack :: Evidence index and auditor-ready artefacts.',NULL,NULL,'Faster, smoother external audits with fewer surprises\nControls that reflect how your business actually operates\nClear ownership and accountability for compliance tasks\nStronger customer and partner trust during due diligence\nReusable evidence across multiple frameworks','IT Application Controls (ITAC) | Yojo Solutions','Identify, design and test automated application controls embedded in your business systems.',0,12),
(13,2,'web-application-vapt','Web Application VAPT','cyber','Authorised security testing','browser','Manual-led testing of web applications against OWASP Top 10, business-logic flaws and authentication weaknesses.','Web applications are the most exposed part of most organisations. Our testers combine tooling with manual exploration to uncover weaknesses that automated scanners miss.','Web application VAPT evaluates an application\'s authentication, session management, authorisation, input handling, business logic and configuration, aligned to OWASP Top 10 and the OWASP Web Security Testing Guide (WSTG).','Customers and frameworks such as ISO 27001, SOC 2 and PCI DSS expect regular independent testing. Logic flaws and access-control issues are frequent root causes of data breaches.',NULL,'Authorisation & scoping :: Signed authorisation, asset list, testing windows, contacts and rules of engagement.\nReconnaissance :: Mapping the authorised attack surface, technologies and entry points.\nAutomated discovery :: Industry-standard scanners to establish baseline coverage.\nManual testing :: Expert-led exploration of business logic, chained weaknesses and false-positive elimination.\nControlled exploitation :: Safe proof-of-concept within agreed limits to demonstrate real impact.\nReporting & retest :: Risk-rated findings, remediation guidance and verification retest.','Authenticated and unauthenticated testing\nRole-based testing across user types\nAgreed environments (staging preferred)\nTesting window and exclusions defined in writing','Authentication & session management\nAuthorisation & access control (IDOR, privilege escalation)\nInjection (SQL, command, template)\nCross-site scripting & client-side issues\nBusiness-logic abuse\nSecurity misconfiguration & headers','Signed scope & rules of engagement\nExecutive and technical VAPT report\nEvidence and proof-of-concept details for each finding\nRemediation tracker (spreadsheet)\nRetest report / closure letter','Executive summary :: Business-level risk overview for leadership.\nTechnical findings :: Each issue with severity (CVSS), affected assets, evidence and reproduction steps.\nRisk heat-map :: Visual distribution of findings by severity and asset.\nWalk-through call :: Findings explained to engineering and management teams.\nRetest letter :: Confirmation of remediated issues after verification.','Prioritised fix list ordered by exploitability and business impact\nDeveloper-friendly guidance with secure configuration and code examples\nCompensating controls where an immediate fix is not feasible\nOptional workshop to address root causes, not just symptoms\nRetest within the agreed window to verify closure','Real-world view of exploitable risk, not just scanner output\nEvidence for ISO 27001, SOC 2, PCI DSS and customer security reviews\nClear priorities for engineering teams\nReduced likelihood and impact of security incidents','Web Application VAPT | Yojo Solutions','Manual-led testing of web applications against OWASP Top 10, business-logic flaws and authentication weaknesses.',1,1),
(14,2,'mobile-application-vapt','Mobile Application VAPT','cyber','Authorised security testing','phone','Security testing of Android and iOS apps and their back-ends against the OWASP MASVS and MASTG.','Mobile apps carry sensitive data and secrets onto devices you do not control. We assess the app binary, local storage, network traffic and supporting APIs.','Mobile VAPT combines static analysis of the app package, dynamic runtime testing on instrumented devices and testing of back-end APIs, aligned to the OWASP Mobile Application Security Verification Standard (MASVS).','App store releases are hard to roll back. Insecure storage, weak certificate validation or hard-coded keys can expose every user of your app.',NULL,'Authorisation & scoping :: Signed authorisation, asset list, testing windows, contacts and rules of engagement.\nReconnaissance :: Mapping the authorised attack surface, technologies and entry points.\nAutomated discovery :: Industry-standard scanners to establish baseline coverage.\nManual testing :: Expert-led exploration of business logic, chained weaknesses and false-positive elimination.\nControlled exploitation :: Safe proof-of-concept within agreed limits to demonstrate real impact.\nReporting & retest :: Risk-rated findings, remediation guidance and verification retest.','Android (APK/AAB) and/or iOS (IPA) builds\nStatic and dynamic analysis\nSupporting API endpoints\nRooted / jailbroken device scenarios','Insecure data storage\nCryptography implementation\nAuthentication & session handling\nNetwork communication & certificate pinning\nPlatform interaction & permissions\nCode tampering & reverse-engineering resilience','Signed scope & rules of engagement\nExecutive and technical VAPT report\nEvidence and proof-of-concept details for each finding\nRemediation tracker (spreadsheet)\nRetest report / closure letter','Executive summary :: Business-level risk overview for leadership.\nTechnical findings :: Each issue with severity (CVSS), affected assets, evidence and reproduction steps.\nRisk heat-map :: Visual distribution of findings by severity and asset.\nWalk-through call :: Findings explained to engineering and management teams.\nRetest letter :: Confirmation of remediated issues after verification.','Prioritised fix list ordered by exploitability and business impact\nDeveloper-friendly guidance with secure configuration and code examples\nCompensating controls where an immediate fix is not feasible\nOptional workshop to address root causes, not just symptoms\nRetest within the agreed window to verify closure','Real-world view of exploitable risk, not just scanner output\nEvidence for ISO 27001, SOC 2, PCI DSS and customer security reviews\nClear priorities for engineering teams\nReduced likelihood and impact of security incidents','Mobile Application VAPT | Yojo Solutions','Security testing of Android and iOS apps and their back-ends against the OWASP MASVS and MASTG.',1,2),
(15,2,'api-security-assessment','API Security Assessment','cyber','Authorised security testing','code','Testing of REST, GraphQL and SOAP APIs against the OWASP API Security Top 10.','APIs power modern products, partner integrations and mobile apps — and they expose data directly. We test how your APIs handle authentication, authorisation and abuse.','An API security assessment reviews documentation (OpenAPI/Swagger, Postman collections) and tests each endpoint for object- and function-level authorisation flaws, excessive data exposure, rate-limiting gaps and injection.','Broken object-level authorisation is among the most common causes of large-scale data exposure. APIs are often less visible to security teams than web front-ends.',NULL,'Authorisation & scoping :: Signed authorisation, asset list, testing windows, contacts and rules of engagement.\nReconnaissance :: Mapping the authorised attack surface, technologies and entry points.\nAutomated discovery :: Industry-standard scanners to establish baseline coverage.\nManual testing :: Expert-led exploration of business logic, chained weaknesses and false-positive elimination.\nControlled exploitation :: Safe proof-of-concept within agreed limits to demonstrate real impact.\nReporting & retest :: Risk-rated findings, remediation guidance and verification retest.','API documentation or collections supplied by you\nMultiple roles / tenants for authorisation testing\nREST, GraphQL or SOAP endpoints\nAgreed request-rate limits','Broken object & function level authorisation\nAuthentication & token handling (JWT, OAuth)\nExcessive data exposure & mass assignment\nRate limiting & resource consumption\nInjection & input validation\nInventory & versioning hygiene','Signed scope & rules of engagement\nExecutive and technical VAPT report\nEvidence and proof-of-concept details for each finding\nRemediation tracker (spreadsheet)\nRetest report / closure letter','Executive summary :: Business-level risk overview for leadership.\nTechnical findings :: Each issue with severity (CVSS), affected assets, evidence and reproduction steps.\nRisk heat-map :: Visual distribution of findings by severity and asset.\nWalk-through call :: Findings explained to engineering and management teams.\nRetest letter :: Confirmation of remediated issues after verification.','Prioritised fix list ordered by exploitability and business impact\nDeveloper-friendly guidance with secure configuration and code examples\nCompensating controls where an immediate fix is not feasible\nOptional workshop to address root causes, not just symptoms\nRetest within the agreed window to verify closure','Real-world view of exploitable risk, not just scanner output\nEvidence for ISO 27001, SOC 2, PCI DSS and customer security reviews\nClear priorities for engineering teams\nReduced likelihood and impact of security incidents','API Security Assessment | Yojo Solutions','Testing of REST, GraphQL and SOAP APIs against the OWASP API Security Top 10.',0,3),
(16,2,'network-vapt','Network VAPT','cyber','Authorised security testing','network','External and internal network penetration testing to identify exposed services and lateral-movement paths.','Your network perimeter and internal segments determine how far an attacker can go. We test from outside and, where authorised, from an assumed-breach position inside.','Network VAPT includes discovery of live hosts and services, vulnerability identification, credential and configuration weaknesses, and controlled exploitation to demonstrate impact and lateral movement within agreed limits.','Unpatched services, weak credentials and flat networks remain leading enablers of ransomware. PCI DSS and many regulators require periodic internal and external network testing.',NULL,'Authorisation & scoping :: Signed authorisation, asset list, testing windows, contacts and rules of engagement.\nReconnaissance :: Mapping the authorised attack surface, technologies and entry points.\nAutomated discovery :: Industry-standard scanners to establish baseline coverage.\nManual testing :: Expert-led exploration of business logic, chained weaknesses and false-positive elimination.\nControlled exploitation :: Safe proof-of-concept within agreed limits to demonstrate real impact.\nReporting & retest :: Risk-rated findings, remediation guidance and verification retest.','Authorised IP ranges and hostnames\nExternal and/or internal perspective\nSegmentation validation\nTesting windows agreed with IT operations','External perimeter & exposed services\nInternal network & segmentation\nPatch and vulnerability exposure\nCredential & authentication weaknesses\nActive Directory attack paths\nWireless networks (if in scope)','Signed scope & rules of engagement\nExecutive and technical VAPT report\nEvidence and proof-of-concept details for each finding\nRemediation tracker (spreadsheet)\nRetest report / closure letter','Executive summary :: Business-level risk overview for leadership.\nTechnical findings :: Each issue with severity (CVSS), affected assets, evidence and reproduction steps.\nRisk heat-map :: Visual distribution of findings by severity and asset.\nWalk-through call :: Findings explained to engineering and management teams.\nRetest letter :: Confirmation of remediated issues after verification.','Prioritised fix list ordered by exploitability and business impact\nDeveloper-friendly guidance with secure configuration and code examples\nCompensating controls where an immediate fix is not feasible\nOptional workshop to address root causes, not just symptoms\nRetest within the agreed window to verify closure','Real-world view of exploitable risk, not just scanner output\nEvidence for ISO 27001, SOC 2, PCI DSS and customer security reviews\nClear priorities for engineering teams\nReduced likelihood and impact of security incidents','Network VAPT | Yojo Solutions','External and internal network penetration testing to identify exposed services and lateral-movement paths.',0,4),
(17,2,'cloud-security-assessment','Cloud Security Assessment','cyber','Configuration review · Authorised testing','cloud','Review of AWS, Azure and GCP configurations, identities and workloads against CIS Benchmarks and provider best practice.','Most cloud incidents stem from misconfiguration and over-privileged identities rather than provider failures. We assess your side of the shared-responsibility model.','A cloud security assessment reviews identity and access management, network exposure, storage permissions, encryption, logging, and workload hardening using read-only access, CIS Benchmarks and provider well-architected guidance.','Rapid cloud adoption often outpaces governance. Public storage buckets, unused admin keys and missing logging are discovered too late without regular review.',NULL,'Authorisation & scoping :: Signed authorisation, asset list, testing windows, contacts and rules of engagement.\nReconnaissance :: Mapping the authorised attack surface, technologies and entry points.\nAutomated discovery :: Industry-standard scanners to establish baseline coverage.\nManual testing :: Expert-led exploration of business logic, chained weaknesses and false-positive elimination.\nControlled exploitation :: Safe proof-of-concept within agreed limits to demonstrate real impact.\nReporting & retest :: Risk-rated findings, remediation guidance and verification retest.','Read-only audit role in agreed accounts/subscriptions\nCIS Benchmark-aligned checks\nOptional authorised penetration testing within provider policy\nMulti-account / landing-zone review','Identity & access management\nNetwork exposure & security groups\nStorage & data protection\nEncryption & key management\nLogging, monitoring & alerting\nContainer & serverless security','Signed scope & rules of engagement\nExecutive and technical VAPT report\nEvidence and proof-of-concept details for each finding\nRemediation tracker (spreadsheet)\nRetest report / closure letter','Executive summary :: Business-