INSERT INTO `industries` (`id`,`slug`,`name`,`icon`,`summary`,`overview`,`risks`,`compliance`,`challenges`,`outcomes`,`sort_order`) VALUES
(1,'banking-financial-services','Banking & Financial Services','bank','Security and IT governance for banks, NBFCs, fintechs and payment businesses operating under close regulatory scrutiny.','Financial institutions hold high-value data and money movement capabilities, making them priority targets. Regulators such as the RBI, SEBI and IRDAI expect mature cyber governance, frequent testing and rapid incident reporting.','Account takeover and payment fraud\nRansomware disrupting core banking\nThird-party and fintech partner exposure\nInsider misuse of privileged access\nAPI abuse in open-banking integrations','RBI Cyber Security Framework & IT Governance Directions\nSEBI CSCRF (for regulated entities)\nPCI DSS\nISO/IEC 27001\nDPDPA 2023','Heavy audit calendars across multiple regulators\nLegacy core systems with limited logging\nEvidencing access reviews at scale\nManaging outsourced IT vendors','Fewer repeat regulatory observations\nTested incident response and reporting readiness\nReduced card-data scope and fraud exposure\nBoard-level visibility of cyber risk',1),
(2,'healthcare','Healthcare','heart','Protecting patient data and clinical continuity for hospitals, diagnostics, pharma and health-tech.','Healthcare combines highly sensitive data with life-critical availability. Connected medical devices, telehealth and cloud records widen the attack surface.','Ransomware halting clinical systems\nExposure of patient records\nInsecure medical and IoT devices\nWeak access control on shared workstations','HIPAA (for US data)\nHITRUST\nDPDPA 2023\nISO/IEC 27001\nABDM health data guidelines (where applicable)','Balancing clinician access with least privilege\nLegacy devices that cannot be patched\nLimited security staffing\nVendor-managed clinical systems','Demonstrable safeguards for health data\nImproved resilience of clinical services\nFaster vendor security approvals with US customers',2),
(3,'it-software','IT & Software Companies','code','Assurance programmes that help IT services and product companies win and retain enterprise clients.','IT and software firms process client data and often have privileged access to client environments. Customers increasingly demand certifications, test reports and contractual security commitments.','Client data leakage through developers or tools\nCompromise of client environments via shared access\nInsecure code released to production\nSupply-chain risks from open-source dependencies','ISO/IEC 27001\nSOC 2\nDPDPA / GDPR as processor\nClient-specific security schedules','Answering lengthy client security questionnaires\nMaintaining evidence across many projects\nSecure SDLC adoption without slowing delivery','Shorter sales cycles with ready assurance artefacts\nFewer client audit findings\nSecure-by-design engineering culture',3),
(4,'saas-startups','SaaS & Technology Startups','rocket','Right-sized security and compliance for fast-growing SaaS companies selling to enterprises.','Startups need to prove security maturity long before they have large security teams. The right sequence of controls and reports unlocks enterprise deals without stalling product velocity.','Cloud misconfiguration\nOver-privileged engineers and service accounts\nAPI authorisation flaws in multi-tenant platforms\nImmature incident response','SOC 2 Type I / II\nISO/IEC 27001\nGDPR / DPDPA\nISO/IEC 42001 for AI products','Limited time and headcount for compliance\nChoosing between SOC 2 and ISO 27001\nBuilding evidence while shipping weekly','Enterprise-ready security posture\nReusable assurance artefacts for sales\nScalable controls that grow with the company',4),
(5,'education','Education','book','Safeguarding student data and academic systems for schools, universities and ed-tech platforms.','Educational institutions manage large, transient user populations, research data and growing online learning platforms — often with constrained IT budgets.','Phishing and credential compromise\nExposure of student and minor data\nRansomware on campus networks\nInsecure third-party learning platforms','DPDPA 2023 (including children\'s data obligations)\nISO/IEC 27001\nGDPR (for international students)','Open, decentralised networks\nHigh user turnover each academic year\nMany small vendors and apps','Protected student data and verifiable parental consent processes\nResilient online learning services\nClear vendor security expectations',5),
(6,'manufacturing','Manufacturing','factory','Bridging IT and OT security for plants, supply chains and industrial operations.','Manufacturers face convergence of IT and operational technology, global supply chains and growing customer requirements for supplier security.','Ransomware stopping production lines\nInsecure remote access to OT\nIntellectual property theft\nSupplier compromise','ISO/IEC 27001\nISO 22301\nCustomer supplier-security requirements\nIEC 62443 alignment (advisory)','Flat networks between office and plant\nLegacy control systems\nLimited downtime for patching','Segmented, monitored plant networks\nTested recovery for production systems\nStronger position in customer audits',6),
(7,'e-commerce','E-commerce','cart','Securing storefronts, payments and customer data for online retailers and marketplaces.','E-commerce businesses handle payments, personal data and high-traffic web applications, with revenue directly tied to availability and customer trust.','Card skimming and payment fraud\nAccount takeover and credential stuffing\nBusiness-logic abuse (coupons, pricing)\nThird-party script and plugin risk','PCI DSS\nDPDPA 2023\nGDPR (for EU customers)\nConsumer Protection (E-Commerce) Rules','Rapid feature releases\nMany plugins and integrations\nPeak-season availability pressure','Reduced payment scope and fraud\nTrusted checkout experience\nPrivacy-compliant marketing practices',7),
(8,'professional-services','Professional Services','briefcase','Confidentiality and client-trust programmes for consulting, legal, accounting and BPO firms.','Professional-services firms are trusted with clients\' most confidential information, making them attractive targets and frequent subjects of client due diligence.','Business email compromise\nLeakage of confidential client documents\nWeak controls at remote and hybrid workers\nInconsistent security across offices','ISO/IEC 27001\nSOC 2 (for outsourced services)\nDPDPA / GDPR\nClient contractual requirements','Partner-led cultures resistant to restrictions\nClient-specific security obligations\nProtecting data on personal devices','Demonstrable confidentiality controls\nFaster client onboarding\nReduced fraud and email-compromise losses',8);
