INSERT INTO `case_studies` (`slug`,`industry_id`,`title`,`client_label`,`challenge`,`assessment`,`improvements`,`remediation`,`outcome`,`is_authorized`,`is_published`,`sort_order`) VALUES
('saas-soc2-readiness-illustrative',4,'SOC 2 readiness for a multi-tenant SaaS platform','Illustrative scenario','A growing SaaS provider was losing enterprise deals because it could not provide an independent assurance report, and controls existed informally in engineers\' heads.','SOC 2 readiness assessment against the Security and Availability criteria, combined with a cloud configuration review and API security assessment.','Undocumented change approvals\nShared administrative cloud credentials\nNo formal vendor review process\nIncident response plan never exercised','Introduced pull-request based change approval with enforced reviews\nMigrated to SSO with MFA and role-based cloud access\nCreated a lightweight vendor risk register\nRan a tabletop exercise and updated the response plan','The organisation entered its CPA firm\'s observation period with documented, operating controls and a reusable evidence library.',0,1,1),
('bank-itgc-illustrative',1,'ITGC uplift ahead of statutory audit','Illustrative scenario','Repeated audit observations on user access reviews and change management were increasing audit effort and drawing regulator attention.','IT General Controls audit across core banking, treasury and general ledger applications, including access, change and operations controls.','Access reviews performed but not evidenced\nDevelopers with production access\nEmergency changes not retrospectively approved','Defined a quarterly access review with system-generated listings\nSeparated deployment rights using a release team\nIntroduced an emergency change log with post-implementation approval','Controls were redesigned and tested before year-end, giving management clear evidence for the statutory auditor.',0,1,2),
('ecommerce-vapt-illustrative',7,'Web and API VAPT for an online retailer','Illustrative scenario','Ahead of a peak sales season, an online retailer needed assurance that its checkout and customer APIs could not be abused.','Authorised web application and API penetration testing covering authentication, authorisation, business logic and payment flow integrations.','Coupon logic could be replayed\nOrder details exposed via predictable identifiers\nMissing rate limiting on login','Server-side coupon state validation\nObject-level authorisation checks in the order service\nRate limiting and bot detection on authentication endpoints','All high-severity issues were fixed and verified in a retest before the sales event.',0,1,3);
